async function db(user, fn) {
  return withDatabaseConnection(pool,user,fn);
}
function user(req) { const value = canonicalDemoUser(req.header('x-demo-user') || 'statewide_admin'); return validUsers.has(value) ? value : 'read_only_viewer'; }
const snapshotEntities = [['crime_incidents','crime_incidents'],['incident_reports','incident_reports'],['evidence_items','evidence_items'],['persons','persons_of_interest'],['person_incident_links','person_incident_links'],['case_files','case_files'],['case_incident_links','case_incident_links'],['semantic_matches','semantic_matches'],['incident_embeddings','incident_report_embeddings'],['person_embeddings','person_profile_embeddings'],['person_narrative_vec','person_narrative_embeddings'],['person_visual_vec','person_visual_embeddings'],['analyst_actions','analyst_actions'],['incident_categories','incident_categories'],['patrol_areas','patrol_areas'],['security_users','security_users'],['security_entitlements','security_user_geo_entitlements'],['social_media_sources','social_media_sources'],['social_media_posts','social_media_posts'],['watched_crime_patterns','watched_crime_patterns'],['social_post_incident_links','social_post_incident_links'],['watched_pattern_incidents','watched_pattern_incidents'],['watched_pattern_posts','watched_pattern_posts']];
const backupTablesFor = (prefix) => snapshotEntities.map(([name,source]) => [`${prefix}_${name}`,source]);
const basicBackupTables = backupTablesFor('basic_bak');
const perthBackupTables = backupTablesFor('perth_bak');
const brisbaneBackupTables = backupTablesFor('brisbane_bak');
const clearBasicDataSql = ['DELETE FROM watched_pattern_posts','DELETE FROM watched_pattern_incidents','DELETE FROM social_post_incident_links','DELETE FROM social_media_posts','DELETE FROM social_media_sources','DELETE FROM watched_crime_patterns','DELETE FROM person_visual_embeddings','DELETE FROM person_narrative_embeddings','DELETE FROM person_profile_embeddings','DELETE FROM incident_report_embeddings','DELETE FROM semantic_matches','DELETE FROM case_incident_links','DELETE FROM person_incident_links','DELETE FROM evidence_items','DELETE FROM incident_reports','DELETE FROM case_files','DELETE FROM persons_of_interest','DELETE FROM crime_incidents','DELETE FROM analyst_actions','DELETE FROM security_user_geo_entitlements','DELETE FROM patrol_areas','DELETE FROM incident_categories','DELETE FROM security_users'];
function restoreProfileDataSql(prefix) { return [
  `INSERT INTO incident_categories (category_code,category_name,severity_band,locality_code,executive_group_code,executive_group_label,display_order,display_color,active) SELECT category_code,category_name,severity_band,locality_code,executive_group_code,executive_group_label,display_order,display_color,active FROM ${prefix}_incident_categories`, `INSERT INTO patrol_areas (area_code,area_name,region_group,centre_lat,centre_lon) SELECT area_code,area_name,region_group,centre_lat,centre_lon FROM ${prefix}_patrol_areas`, `INSERT INTO security_users SELECT * FROM ${prefix}_security_users`, `INSERT INTO security_user_geo_entitlements (user_name,patrol_area_id) SELECT b.user_name,p.patrol_area_id FROM ${prefix}_security_entitlements b JOIN ${prefix}_patrol_areas bp ON bp.patrol_area_id=b.patrol_area_id JOIN patrol_areas p ON p.area_code=bp.area_code`,
  `INSERT INTO crime_incidents (incident_ref,category_id,patrol_area_id,incident_status,occurred_at,location_type,suburb,latitude,longitude,address_line_1,address_locality,address_region,address_postcode,address_country_code,address_precision,address_enrichment_source,modus_operandi,property_category,vehicle_descriptor,incident_attributes,created_at) SELECT b.incident_ref,c.category_id,p.patrol_area_id,b.incident_status,b.occurred_at,b.location_type,b.suburb,b.latitude,b.longitude,b.address_line_1,b.address_locality,b.address_region,b.address_postcode,b.address_country_code,b.address_precision,b.address_enrichment_source,b.modus_operandi,b.property_category,b.vehicle_descriptor,b.incident_attributes,b.created_at FROM ${prefix}_crime_incidents b JOIN ${prefix}_incident_categories bc ON bc.category_id=b.category_id JOIN incident_categories c ON c.category_code=bc.category_code JOIN ${prefix}_patrol_areas bp ON bp.patrol_area_id=b.patrol_area_id JOIN patrol_areas p ON p.area_code=bp.area_code`,
  `INSERT INTO incident_reports (incident_id,report_summary,report_text,embedding_text,enrichments,created_at) SELECT i.incident_id,b.report_summary,b.report_text,b.embedding_text,b.enrichments,b.created_at FROM ${prefix}_incident_reports b JOIN ${prefix}_crime_incidents bi ON bi.incident_id=b.incident_id JOIN crime_incidents i ON i.incident_ref=bi.incident_ref`,
  `INSERT INTO evidence_items (incident_id,evidence_type,evidence_metadata,created_at) SELECT i.incident_id,b.evidence_type,b.evidence_metadata,b.created_at FROM ${prefix}_evidence_items b JOIN ${prefix}_crime_incidents bi ON bi.incident_id=b.incident_id JOIN crime_incidents i ON i.incident_ref=bi.incident_ref`,
  `INSERT INTO persons_of_interest (person_ref,display_name,alias_name,person_status,portrait_variant,narrative_summary,created_at,portrait_asset_uri,portrait_alt_text) SELECT person_ref,display_name,alias_name,person_status,portrait_variant,narrative_summary,created_at,portrait_asset_uri,portrait_alt_text FROM ${prefix}_persons`,
  `INSERT INTO person_incident_links (person_id,incident_id,connection_type,link_summary,created_at) SELECT p.person_id,i.incident_id,b.connection_type,b.link_summary,b.created_at FROM ${prefix}_person_incident_links b JOIN ${prefix}_persons bp ON bp.person_id=b.person_id JOIN persons_of_interest p ON p.person_ref=bp.person_ref JOIN ${prefix}_crime_incidents bi ON bi.incident_id=b.incident_id JOIN crime_incidents i ON i.incident_ref=bi.incident_ref`,
  `INSERT INTO case_files (case_ref,case_status,pattern_label,patrol_area_id,created_at) SELECT b.case_ref,b.case_status,b.pattern_label,p.patrol_area_id,b.created_at FROM ${prefix}_case_files b JOIN ${prefix}_patrol_areas bp ON bp.patrol_area_id=b.patrol_area_id JOIN patrol_areas p ON p.area_code=bp.area_code`,
  `INSERT INTO case_incident_links (case_id,incident_id) SELECT c.case_id,i.incident_id FROM ${prefix}_case_incident_links b JOIN ${prefix}_case_files bc ON bc.case_id=b.case_id JOIN case_files c ON c.case_ref=bc.case_ref JOIN ${prefix}_crime_incidents bi ON bi.incident_id=b.incident_id JOIN crime_incidents i ON i.incident_ref=bi.incident_ref`,
  `INSERT INTO semantic_matches (source_incident_id,matched_incident_id,similarity_score,match_reason) SELECT source.incident_id,target.incident_id,b.similarity_score,b.match_reason FROM ${prefix}_semantic_matches b JOIN ${prefix}_crime_incidents bs ON bs.incident_id=b.source_incident_id JOIN crime_incidents source ON source.incident_ref=bs.incident_ref JOIN ${prefix}_crime_incidents bt ON bt.incident_id=b.matched_incident_id JOIN crime_incidents target ON target.incident_ref=bt.incident_ref`,
  `INSERT INTO incident_report_embeddings (incident_id,embedding_model,embedding,created_at) SELECT i.incident_id,b.embedding_model,b.embedding,b.created_at FROM ${prefix}_incident_embeddings b JOIN ${prefix}_crime_incidents bi ON bi.incident_id=b.incident_id JOIN crime_incidents i ON i.incident_ref=bi.incident_ref`,
  `INSERT INTO person_profile_embeddings (person_id,embedding_model,embedding,created_at) SELECT p.person_id,b.embedding_model,b.embedding,b.created_at FROM ${prefix}_person_embeddings b JOIN ${prefix}_persons bp ON bp.person_id=b.person_id JOIN persons_of_interest p ON p.person_ref=bp.person_ref`,
  `INSERT INTO analyst_actions (user_name,action_type,payload,created_at) SELECT user_name,action_type,payload,created_at FROM ${prefix}_analyst_actions`
]; }
const restoreBasicDataSql = restoreProfileDataSql('basic_bak');
const restorePerthDataSql = restoreProfileDataSql('perth_bak');
function setupAdmin(req,res) { if(req.demoUser!=='statewide_admin') { res.status(403).json({error:'IncidentData Setup changes are restricted to statewide_admin.'}); return false; } return true; }
const {profileConfig,requestedProfile,standardRestoreCodes,nrtRestoreCodes,standardOnlyProfiles}=require('./setup-profile-selection');
async function profileStatus(demoUser,code) { return profileLibrary.status(demoUser,code); }
const restoreSelectedProfile=createProfileRestorer({db,profileStatus});
const publicDemoAuth=require('./public-demo-auth').fromEnvironment();
if(publicDemoAuth){app.set('trust proxy','loopback');app.use(publicDemoAuth);}
app.get('/api/session',(req,res)=>res.json(req.demoPrincipal||{fixedPersona:false}));
app.use(helmet({contentSecurityPolicy:false}));
app.use(cors({origin: process.env.FRONTEND_URL || true}));
app.use(morgan('tiny')); app.use(express.json({limit:'10mb'}));
app.use('/api', (req,res,next) => { res.set('Cache-Control','no-store'); req.demoUser=user(req); next(); });
app.use('/api', (req,res,next) => {
  if(process.env.CRIMEDATA_READ_ONLY_REVIEW==='1' && !['GET','HEAD'].includes(req.method))return res.status(405).json({error:'This isolated application review is read-only; no mutation was executed.'});
  next();
});
app.use('/api', ops.requestContext);
createAiOps(db).register(app);
// Preserve Data Room source filenames/previews verbatim; do not apply presentation-copy rewriting.
const dataRoom = require('./data-room').registerDataRoom(app, db);
// Exact source text and offsets must not pass through presentation rewriting.
require('./evidence-intelligence').registerEvidenceIntelligence(app, db);
require('./investigation-trail').registerInvestigationTrail(app, db);
// Stored history is served verbatim, before display-copy rewriting middleware.
require('./poi-identifier-detail').registerPoiIdentifierDetail(app,db);
const agentHistory = createAgentHistory(db, presentationCopy);
agentHistory.register(app);
const profileLibrary=createProfileLibrary(db,{restoreCodes:standardRestoreCodes,nrtRestoreCodes});
profileLibrary.register(app);
// Discovery remains data-driven; only explicitly supported profiles can restore.
// European and validated USA profiles support standard restore only.
app.use('/api/setup',require('./setup-mutation-guard').setupMutationGuard({legacyProfiles:profileConfig,standardOnlyProfiles:[...standardOnlyProfiles],db}));
app.use('/api', (req,res,next) => {
  const sendJson = res.json.bind(res);
  res.json = (payload) => sendJson(presentationCopy(payload));
  next();
});

app.get('/api/health', async (req,res) => { try { const r=await db(req.demoUser,c=>c.execute("select 'healthy' status from dual")); res.json({status:'healthy',database:r.rows[0],security:'Deep Sec policy baseline + scoped database view'}); } catch(e) { res.status(503).json({status:'unhealthy',error:e.message}); } });
require('./result-relationships').registerResultRelationships(app, db);

app.post('/api/setup/backup', async (req,res) => { if(!setupAdmin(req,res))return; const profileCode=requestedProfile(req.body?.profileCode),config=profileConfig[profileCode]; try { await db(req.demoUser,c=>c.execute(`BEGIN z_base_dataset_admin.capture_active_profile(:profileCode,:profileName,:cityLabel,:profileNotes); END;`,{profileCode,profileName:config.name,cityLabel:config.city,profileNotes:`Captured from the active operational dataset on ${new Date().toISOString().slice(0,10)}.`}));res.json({message:`Active operational data captured to the ${config.name} Z_BASE profile.`,...(await profileStatus(req.demoUser,profileCode))}); } catch(e){console.error('Z_BASE profile capture error:',e);res.status(500).json({error:e.message});} });
app.post('/api/setup/delete', async (req,res) => { if(!setupAdmin(req,res))return; const profileCode=requestedProfile(req.body?.profileCode),config=profileConfig[profileCode],confirmation=`DELETE ${config.city.toUpperCase()} DATA SET`; if(req.body?.confirmation!==confirmation)return res.status(400).json({error:`Enter ${confirmation} to confirm deletion.`}); try { await db(req.demoUser,async c=>{for(const statement of clearBasicDataSql)await c.execute(statement);await c.execute(`UPDATE demo_data_profiles SET profile_status=CASE WHEN profile_code=:profileCode THEN 'unloaded' WHEN profile_status='active' THEN 'available' ELSE profile_status END`,{profileCode});await c.commit();});res.json({message:`${config.name} deleted from the operational dataset. Its recoverable snapshot remains available to load.`,...(await profileStatus(req.demoUser,profileCode))}); } catch(e){console.error('Profile delete error:',e);res.status(500).json({error:e.message});} });
app.post('/api/setup/load', async (req,res) => { if(!setupAdmin(req,res))return; const profileCode=requestedProfile(req.body?.profileCode); try { const status=await restoreSelectedProfile(req.demoUser,profileCode,req.body.expectedActiveProfileCode);res.json({message:`${status.profile.PROFILE_NAME} restored and verified.`,...status}); } catch(e){console.error('Z_BASE profile restore error:',e);res.status(500).json({error:restoreErrorMessage(e),verificationRequired:true});} });
app.post('/api/setup/load-nrt', async (req,res) => { if(!setupAdmin(req,res))return; const profileCode=requestedProfile(req.body?.profileCode); if(!nrtRestoreCodes.includes(profileCode))return res.status(400).json({error:'NRT is available only for supported Australian profiles.'}); try { const status=await restoreSelectedProfile(req.demoUser,profileCode,req.body.expectedActiveProfileCode,true);res.json({message:`${status.profile.PROFILE_NAME} restored and verified in NRT mode. Incident occurrence times were shifted together; the saved snapshot is unchanged.`,...status}); } catch(e){console.error('NRT Z_BASE profile restore error:',e);res.status(500).json({error:restoreErrorMessage(e),verificationRequired:true});} });
app.get('/api/setup/export', async (req,res) => { if(!setupAdmin(req,res))return; try { const snapshot=await db(req.demoUser,async c=>{const context=await require('./profile-library').activeContext(c);const [incidents,reports,persons,cases,evidence,personLinks,caseLinks]=await Promise.all([c.execute(`SELECT * FROM crime_incidents ORDER BY incident_id`),c.execute(`SELECT report_id,incident_id,report_summary,DBMS_LOB.SUBSTR(report_text,4000,1) report_text,embedding_text,enrichments,created_at FROM incident_reports ORDER BY report_id`),c.execute(`SELECT * FROM persons_of_interest ORDER BY person_id`),c.execute(`SELECT * FROM case_files ORDER BY case_id`),c.execute(`SELECT * FROM evidence_items ORDER BY evidence_id`),c.execute(`SELECT * FROM person_incident_links ORDER BY person_id,incident_id`),c.execute(`SELECT * FROM case_incident_links ORDER BY case_id,incident_id`)]);return {profile:context.profileCode,city:context.cityLabel,timeZone:context.timeZone,exportedAt:new Date().toISOString(),notice:context.notice,exportScope:'Active core relational profile; in-database snapshot separately preserves vector and audit tables.',data:{crimeIncidents:incidents.rows,incidentReports:reports.rows,persons:persons.rows,cases:cases.rows,evidence:evidence.rows,personIncidentLinks:personLinks.rows,caseIncidentLinks:caseLinks.rows}};});res.set({'Content-Type':'application/json','Content-Disposition':`attachment; filename="${snapshot.profile.toLowerCase().replace(/[^a-z0-9_-]/g,'_')}-data-set-profile-${new Date().toISOString().slice(0,10)}.json"`});res.send(JSON.stringify(snapshot,null,2)); } catch(e){console.error('Profile export error:',e);res.status(500).json({error:e.message});} });
app.get('/api/users', async (req,res) => { const r=await db(req.demoUser,c=>c.execute(`SELECT u.user_name,u.role_name,u.display_name,LISTAGG(p.area_name, ', ') WITHIN GROUP(ORDER BY p.area_name) areas FROM security_users u LEFT JOIN security_user_geo_entitlements e ON e.user_name=u.user_name LEFT JOIN patrol_areas p ON p.patrol_area_id=e.patrol_area_id GROUP BY u.user_name,u.role_name,u.display_name ORDER BY u.user_name`)); res.json(r.rows); });
app.get('/api/dashboard', async (req,res) => { const r=await db(req.demoUser,async c => { const [summary,categories,areas,signals,watchedPatterns]=await Promise.all([
  c.execute(`SELECT COUNT(*) incident_count, COUNT(DISTINCT cat.executive_group_code) category_count, SUM(CASE WHEN i.incident_status NOT IN ('resolved','closed_no_further_action') THEN 1 ELSE 0 END) open_count FROM secure_crime_incidents_v i JOIN incident_categories cat ON cat.category_id=i.category_id WHERE cat.active=1`),
  c.execute(`SELECT cat.executive_group_code category_code,cat.executive_group_label category_name,MIN(cat.display_order) display_order,MIN(cat.display_color) display_color,COUNT(*) count,COUNT(DISTINCT cat.category_id) detail_category_count FROM secure_crime_incidents_v i JOIN incident_categories cat ON cat.category_id=i.category_id WHERE cat.active=1 GROUP BY cat.executive_group_code,cat.executive_group_label ORDER BY MIN(cat.display_order)`),
  c.execute(`SELECT p.area_name,COUNT(*) count FROM secure_crime_incidents_v i JOIN patrol_areas p ON p.patrol_area_id=i.patrol_area_id GROUP BY p.area_name ORDER BY p.area_name`),
  c.execute(`SELECT COUNT(DISTINCT s.post_ref) post_count_72h,COUNT(DISTINCT s.source_code) source_count_72h,COUNT(DISTINCT CASE WHEN s.momentum_flag IN ('elevated','critical') THEN s.post_ref END) elevated_count_72h,COUNT(DISTINCT CASE WHEN i.incident_ref IS NOT NULL AND l.review_status='reviewed' THEN s.post_ref END) linked_post_count,COUNT(DISTINCT CASE WHEN i.incident_ref IS NOT NULL AND l.review_status='reviewed' THEN i.incident_ref END) linked_incident_count FROM secure_social_media_posts_v s LEFT JOIN social_post_incident_links l ON l.post_ref=s.post_ref LEFT JOIN secure_crime_incidents_v i ON i.incident_ref=l.incident_ref WHERE s.posted_at >= (SELECT MAX(posted_at) FROM secure_social_media_posts_v)-INTERVAL '72' HOUR`),
  c.execute(`SELECT w.pattern_code,w.pattern_name,w.pattern_summary,w.why_watch,w.pattern_kind,w.pattern_status,w.search_query,w.case_ref,w.display_color,(SELECT COUNT(*) FROM watched_pattern_incidents wi JOIN secure_crime_incidents_v i ON i.incident_ref=wi.incident_ref WHERE wi.pattern_code=w.pattern_code) incident_count,(SELECT COUNT(*) FROM watched_pattern_posts wp JOIN secure_social_media_posts_v s ON s.post_ref=wp.post_ref WHERE wp.pattern_code=w.pattern_code) post_count FROM watched_crime_patterns w WHERE w.active=1 AND w.activate_ui='Y' ORDER BY w.display_order`)
]); return {summary:summary.rows[0],categories:categories.rows,areas:areas.rows,signals:signals.rows[0],watchedPatterns:watchedPatterns.rows}; }); res.json(r); });
app.get('/api/dashboard/crime-category-signal-velocity', async (req,res) => { const horizonMap={ '1h':1,'2h':2,'24h':24,'48h':48,'7d':168,'30d':720,'60d':1440,'1y':8760,'2y':17520 }; const horizon=horizonMap[req.query.window]||720; const hourly=horizon<=48; const bucket=hourly?`TRUNC(i.occurred_at, 'HH')`:`TRUNC(i.occurred_at)`; const label=hourly?`TO_CHAR(${bucket}, 'DD Mon HH24:MI')`:`TO_CHAR(${bucket}, 'DD Mon')`; const key=hourly?`TO_CHAR(${bucket}, 'YYYY-MM-DD HH24:MI')`:`TO_CHAR(${bucket}, 'YYYY-MM-DD')`; const result=await db(req.demoUser,async c=>{const [groups,signals]=await Promise.all([
  c.execute(`SELECT cat.executive_group_code category_code,cat.executive_group_label category_name,MIN(cat.display_order) display_order,MIN(cat.display_color) display_color FROM secure_crime_incidents_v i JOIN incident_categories cat ON cat.category_id=i.category_id WHERE cat.active=1 GROUP BY cat.executive_group_code,cat.executive_group_label ORDER BY MIN(cat.display_order)`),
  c.execute(`SELECT ${label} day_label,${key} day_key,cat.executive_group_code category_code,COUNT(*) signal_count FROM secure_crime_incidents_v i JOIN incident_categories cat ON cat.category_id=i.category_id WHERE cat.active=1 AND i.occurred_at >= (SELECT MAX(occurred_at) FROM secure_crime_incidents_v) - NUMTODSINTERVAL(:hours, 'HOUR') GROUP BY ${bucket},cat.executive_group_code ORDER BY day_key,cat.executive_group_code`,{hours:horizon})
]);return {groups:groups.rows,signals:signals.rows};});const pointMap=new Map();for(const row of result.signals){const point=pointMap.get(row.DAY_KEY)||{DAY_KEY:row.DAY_KEY,DAY_LABEL:row.DAY_LABEL,COUNTS:{},TOTAL_SIGNAL_COUNT:0};point.COUNTS[row.CATEGORY_CODE]=Number(row.SIGNAL_COUNT);point.TOTAL_SIGNAL_COUNT+=Number(row.SIGNAL_COUNT);pointMap.set(row.DAY_KEY,point);}res.json({groups:result.groups,points:[...pointMap.values()]}); });
app.get('/api/community-signals/summary', async (req,res) => { try { const summary=await db(req.demoUser,c=>require('./community-signals-summary').communitySignalSummary(c));res.json(summary); } catch(e){console.error('Community signal summary error:',e);res.status(500).json({error:e.message});} });
app.get('/api/community-signals/posts', async (req,res) => { const momentum=String(req.query.momentum||'').trim().toLowerCase(),patternCode=String(req.query.patternCode||'').trim().toUpperCase(),linkedOnly=String(req.query.linkedOnly||'')==='1',limit=Math.min(Math.max(Number(req.query.limit)||12,1),50);const allowedMomentum=new Set(['normal','rising','elevated','critical']);const where=[],binds={limit};if(allowedMomentum.has(momentum)){where.push('s.momentum_flag=:momentum');binds.momentum=momentum;}if(patternCode){where.push('s.topic_code=:patternCode');binds.patternCode=patternCode;}if(linkedOnly)where.push(`EXISTS (SELECT 1 FROM social_post_incident_links lx JOIN secure_crime_incidents_v ix ON ix.incident_ref=lx.incident_ref WHERE lx.post_ref=s.post_ref AND lx.review_status='reviewed')`);try{const r=await db(req.demoUser,c=>c.execute(`SELECT s.post_ref,s.posted_at,s.post_text,s.topic_code,s.topic_label,s.executive_group_code,s.suburb,s.geo_precision,s.reach_count,s.reshare_count,s.reply_count,s.signal_score,s.momentum_flag,s.verification_status,src.source_name,src.platform_label,src.source_type,links.linked_incident_refs,links.linked_incident_count,links.max_link_confidence FROM secure_social_media_posts_v s JOIN social_media_sources src ON src.source_code=s.source_code LEFT JOIN (SELECT l.post_ref,LISTAGG(l.incident_ref,', ') WITHIN GROUP(ORDER BY l.incident_ref) linked_incident_refs,COUNT(DISTINCT l.incident_ref) linked_incident_count,MAX(l.link_confidence) max_link_confidence FROM social_post_incident_links l JOIN secure_crime_incidents_v i ON i.incident_ref=l.incident_ref WHERE l.review_status='reviewed' GROUP BY l.post_ref) links ON links.post_ref=s.post_ref ${where.length?`WHERE ${where.join(' AND ')}`:''} ORDER BY s.signal_score DESC,s.posted_at DESC FETCH FIRST :limit ROWS ONLY`,binds));res.json({posts:r.rows,count:r.rows.length,filters:{momentum:allowedMomentum.has(momentum)?momentum:'',patternCode,linkedOnly},notice:'Simulated public posts are unverified external signals. Reviewed links provide comparison context only and are not evidence.'});}catch(e){console.error('Community signal feed error:',e);res.status(500).json({error:e.message});} });
app.get('/api/community-signals/trend', async (req,res) => { const hours=Math.min(Math.max(Number(req.query.hours)||72,24),720),hourly=hours<=168,bucket=hourly?`TRUNC(posted_at,'HH')`:`TRUNC(posted_at)`,key=hourly?`TO_CHAR(${bucket},'YYYY-MM-DD HH24:MI')`:`TO_CHAR(${bucket},'YYYY-MM-DD')`;try{const r=await db(req.demoUser,c=>c.execute(`SELECT ${key} time_bucket,topic_code,COUNT(*) post_count,ROUND(AVG(signal_score),1) avg_signal_score FROM secure_social_media_posts_v WHERE posted_at >= (SELECT MAX(posted_at) FROM secure_social_media_posts_v)-NUMTODSINTERVAL(:hours,'HOUR') GROUP BY ${bucket},topic_code ORDER BY time_bucket,topic_code`,{hours}));res.json({hours,results:r.rows});}catch(e){console.error('Community signal trend error:',e);res.status(500).json({error:e.message});} });
