app.get('/api/watched-patterns/:patternCode/map', async (req,res) => {
  const patternCode=String(req.params.patternCode||'').trim().toUpperCase();
  if(!patternCode)return res.status(400).json({error:'A watched pattern code is required.'});
  const select=`FROM watched_pattern_incidents wi JOIN secure_crime_incidents_v i ON i.incident_ref=wi.incident_ref JOIN incident_categories cat ON cat.category_id=i.category_id JOIN patrol_areas p ON p.patrol_area_id=i.patrol_area_id JOIN secure_incident_reports_v r ON r.incident_id=i.incident_id WHERE wi.pattern_code=:patternCode AND cat.active=1`;
  try {
    const result=await db(req.demoUser,async c=>{
      const [rows,coverage,summary,bounds]=await Promise.all([
        c.execute(`SELECT i.incident_id,i.incident_ref,i.suburb,i.incident_status,i.occurred_at,i.location_type,i.modus_operandi,i.latitude,i.longitude,cat.executive_group_label category_name,cat.category_name detailed_category_name,cat.display_color,cat.severity_band,p.area_name,r.report_summary ${select} ORDER BY i.occurred_at DESC`,{patternCode}),
        c.execute(`SELECT i.suburb,ROUND(AVG(i.latitude),6) latitude,ROUND(AVG(i.longitude),6) longitude,COUNT(*) incident_count ${select} GROUP BY i.suburb ORDER BY incident_count DESC,i.suburb`,{patternCode}),
        c.execute(`SELECT COUNT(*) total_count,SUM(CASE WHEN i.incident_status NOT IN ('resolved','closed_no_further_action') THEN 1 ELSE 0 END) open_count ${select}`,{patternCode}),
        c.execute(`SELECT TO_CHAR(MIN(i.occurred_at),'YYYY-MM-DD') earliest_date,TO_CHAR(MAX(i.occurred_at),'YYYY-MM-DD') latest_date ${select}`,{patternCode})
      ]);
      return {rows:rows.rows,coverage:coverage.rows,summary:summary.rows[0],timeBounds:bounds.rows[0],limit:rows.rows.length};
    });
    res.json(result);
  } catch(e){console.error('Watched pattern map error:',e);res.status(500).json({error:e.message});}
});
