app.get('/api/incidents/filters', async (req,res) => { try { const r=await db(req.demoUser,async c=>{const [categories,suburbs,statuses,areas]=await Promise.all([c.execute(`SELECT cat.executive_group_label value,MIN(cat.display_order) display_order,MIN(cat.display_color) display_color,COUNT(*) record_count FROM secure_crime_incidents_v i JOIN incident_categories cat ON cat.category_id=i.category_id WHERE cat.active=1 GROUP BY cat.executive_group_code,cat.executive_group_label ORDER BY MIN(cat.display_order)`),c.execute(`SELECT suburb value,COUNT(*) record_count FROM secure_crime_incidents_v GROUP BY suburb ORDER BY value`),c.execute(`SELECT incident_status value,COUNT(*) record_count FROM secure_crime_incidents_v GROUP BY incident_status ORDER BY value`),c.execute(`SELECT p.area_name value,COUNT(*) record_count FROM secure_crime_incidents_v i JOIN patrol_areas p ON p.patrol_area_id=i.patrol_area_id GROUP BY p.area_name ORDER BY value`)]);return {categories:categories.rows,suburbs:suburbs.rows,statuses:statuses.rows,areas:areas.rows};});res.json(r);} catch(e){console.error('Incident filter LOV error:',e);res.status(500).json({error:e.message});} });
app.get('/api/incidents', async (req,res) => { const q=String(req.query.q||'').trim().toLowerCase(),category=String(req.query.category||'').trim(),suburb=String(req.query.suburb||'').trim(),status=String(req.query.status||'').trim(),area=String(req.query.area||'').trim(),limit=Math.min(Math.max(Number(req.query.limit)||100,1),200); try { const r=await db(req.demoUser,c=>c.execute(`SELECT * FROM (SELECT i.incident_id,i.incident_ref,i.suburb,i.incident_status,i.occurred_at,i.location_type,i.modus_operandi,i.latitude,i.longitude,cat.executive_group_label category_name,cat.category_name detailed_category_name,cat.display_color,cat.severity_band,p.area_name,r.report_summary FROM secure_crime_incidents_v i JOIN incident_categories cat ON cat.category_id=i.category_id JOIN patrol_areas p ON p.patrol_area_id=i.patrol_area_id JOIN secure_incident_reports_v r ON r.incident_id=i.incident_id WHERE cat.active=1 AND (:q IS NULL OR LOWER(i.incident_ref) LIKE '%'||:q||'%' OR LOWER(i.suburb) LIKE '%'||:q||'%' OR LOWER(cat.category_name) LIKE '%'||:q||'%' OR LOWER(cat.executive_group_label) LIKE '%'||:q||'%' OR LOWER(NVL(i.modus_operandi,'x')) LIKE '%'||:q||'%' OR LOWER(r.report_summary) LIKE '%'||:q||'%' OR DBMS_LOB.INSTR(LOWER(r.report_text),:q)>0) AND (:category IS NULL OR cat.executive_group_label=:category) AND (:suburb IS NULL OR i.suburb=:suburb) AND (:status IS NULL OR i.incident_status=:status) AND (:area IS NULL OR p.area_name=:area) ORDER BY i.occurred_at DESC) WHERE ROWNUM <= :limit`, {q:q||null,category:category||null,suburb:suburb||null,status:status||null,area:area||null,limit})); res.json(r.rows); } catch(e){console.error('Incident search error:',e);res.status(500).json({error:e.message});} });
