app.get('/api/incidents/:incidentRef', async (req,res) => { const incidentRef=String(req.params.incidentRef||'').trim(); try { const result=await db(req.demoUser,async c=>{const incident=await c.execute(`SELECT i.incident_id,i.incident_ref,i.incident_status,i.occurred_at,i.location_type,i.suburb,i.latitude,i.longitude,i.address_line_1,i.address_locality,i.address_region,i.address_postcode,i.address_country_code,i.address_precision,i.modus_operandi,i.property_category,i.vehicle_descriptor,i.incident_attributes,cat.executive_group_label category_name,cat.category_name detailed_category_name,cat.executive_group_code,cat.severity_band,cat.display_color,p.area_name,r.report_summary,DBMS_LOB.SUBSTR(r.report_text,4000,1) report_text FROM secure_crime_incidents_v i JOIN incident_categories cat ON cat.category_id=i.category_id JOIN patrol_areas p ON p.patrol_area_id=i.patrol_area_id JOIN secure_incident_reports_v r ON r.incident_id=i.incident_id WHERE i.incident_ref=:incidentRef`,{incidentRef}); if(!incident.rows.length)return null; const id=incident.rows[0].INCIDENT_ID; const [evidence,people]=await Promise.all([c.execute(`SELECT evidence_type,created_at FROM evidence_items WHERE incident_id=:id ORDER BY evidence_id`,{id}),c.execute(`SELECT p.person_ref,p.alias_name,p.person_status,l.connection_type,l.link_summary FROM person_incident_links l JOIN secure_persons_of_interest_v p ON p.person_id=l.person_id WHERE l.incident_id=:id ORDER BY p.person_ref`,{id})]);return {incident:incident.rows[0],evidence:evidence.rows,people:people.rows};}); if(!result)return res.status(404).json({error:'No authorised incident record found.'});res.json(result); } catch(e){console.error('Incident detail error:',e);res.status(500).json({error:e.message});} });
