app.get('/api/persons/:personRef', async (req,res) => { const personRef=String(req.params.personRef||'').trim(); try { const result=await db(req.demoUser,async c=>{const person=await c.execute(`SELECT p.person_id,p.person_ref,p.display_name,p.alias_name,p.person_status,p.portrait_variant,p.portrait_asset_uri,p.portrait_alt_text,p.narrative_summary,DBMS_LOB.SUBSTR(p.narrative_text,4000,1) narrative_text,p.profile_attributes,p.created_at,(SELECT COUNT(*) FROM person_incident_links l JOIN secure_crime_incidents_v i ON i.incident_id=l.incident_id WHERE l.person_id=p.person_id) scoped_incident_count FROM secure_persons_of_interest_v p WHERE p.person_ref=:personRef`,{personRef});if(!person.rows.length)return null;const [incidentLinks,assets]=await Promise.all([c.execute(`SELECT i.incident_ref,cat.category_name,l.connection_type,l.link_summary FROM person_incident_links l JOIN secure_crime_incidents_v i ON i.incident_id=l.incident_id JOIN incident_categories cat ON cat.category_id=i.category_id WHERE l.person_id=:personId ORDER BY i.occurred_at DESC FETCH FIRST 6 ROWS ONLY`,{personId:person.rows[0].PERSON_ID}),c.execute(`SELECT asset_ref,asset_kind,asset_uri,mime_type,asset_caption,embedding_model,created_at FROM person_visual_embeddings WHERE person_id=:personId ORDER BY CASE asset_kind WHEN 'reference_portrait' THEN 1 ELSE 2 END,created_at`,{personId:person.rows[0].PERSON_ID})]);return {person:person.rows[0],incidentLinks:incidentLinks.rows,assets:assets.rows};});if(!result)return res.status(404).json({error:'No authorised person profile found.'});res.json(result); } catch(e) { console.error('POI detail error:',e); res.status(500).json({error:e.message}); } });
