app.get('/api/graph/network', async (req,res) => {
  const caseRef=String(req.query.caseRef||'').trim();
  const depth=Math.min(Math.max(Number(req.query.depth)||2,1),3);
  if(!caseRef)return res.status(400).json({error:'caseRef is required'});
  try {
    const result=await db(req.demoUser,async c=>{
      const center=await c.execute(`SELECT c.case_id,c.case_ref,c.pattern_label,c.case_status FROM case_files c WHERE c.case_ref=:caseRef AND EXISTS (SELECT 1 FROM case_incident_links l JOIN secure_crime_incidents_v i ON i.incident_id=l.incident_id WHERE l.case_id=c.case_id)`,{caseRef});
      if(!center.rows.length)return null;
      const caseId=center.rows[0].CASE_ID;
      const incidents=await c.execute(`SELECT i.incident_id,i.incident_ref,i.suburb,i.incident_status,i.modus_operandi,i.address_line_1,i.address_postcode,cat.category_name FROM case_incident_links l JOIN secure_crime_incidents_v i ON i.incident_id=l.incident_id JOIN incident_categories cat ON cat.category_id=i.category_id WHERE l.case_id=:caseId ORDER BY i.occurred_at FETCH FIRST 24 ROWS ONLY`,{caseId});
      const evidence=depth>=2?await c.execute(`SELECT e.evidence_id,e.incident_id,e.evidence_type,e.created_at,JSON_VALUE(e.evidence_metadata,'$.observed_detail') observed_detail,JSON_VALUE(e.evidence_metadata,'$.shared_marker') shared_marker,JSON_VALUE(e.evidence_metadata,'$.asset_uri') asset_uri,JSON_VALUE(e.evidence_metadata,'$.asset_caption') asset_caption FROM evidence_items e JOIN secure_crime_incidents_v i ON i.incident_id=e.incident_id WHERE e.incident_id IN (SELECT l.incident_id FROM case_incident_links l WHERE l.case_id=:caseId) ORDER BY e.evidence_id FETCH FIRST 30 ROWS ONLY`,{caseId}):{rows:[]};
      const people=depth>=2?await c.execute(`SELECT p.person_id,p.person_ref,p.display_name,p.alias_name,p.person_status,p.portrait_variant,p.portrait_asset_uri,l.incident_id,l.connection_type FROM persons_of_interest p JOIN person_incident_links l ON l.person_id=p.person_id JOIN secure_crime_incidents_v i ON i.incident_id=l.incident_id WHERE l.incident_id IN (SELECT incident_id FROM case_incident_links WHERE case_id=:caseId) FETCH FIRST 18 ROWS ONLY`,{caseId}):{rows:[]};
      const similarities=depth>=3?await c.execute(`SELECT s.match_id,s.source_incident_id,s.matched_incident_id,s.similarity_score,s.match_reason FROM semantic_matches s JOIN secure_crime_incidents_v source_i ON source_i.incident_id=s.source_incident_id JOIN secure_crime_incidents_v matched_i ON matched_i.incident_id=s.matched_incident_id WHERE s.source_incident_id IN (SELECT incident_id FROM case_incident_links WHERE case_id=:caseId) AND s.matched_incident_id IN (SELECT incident_id FROM case_incident_links WHERE case_id=:caseId) ORDER BY s.similarity_score DESC`,{caseId}):{rows:[]};
      const personNodes=Array.from(new Map(people.rows.map(p=>[p.PERSON_ID,{id:'person-'+p.PERSON_ID,type:'person',label:p.PERSON_REF,PERSON_REF:p.PERSON_REF,detail:p.ALIAS_NAME+' · '+p.PERSON_STATUS,avatar:p.PORTRAIT_VARIANT,PORTRAIT_ASSET_URI:p.PORTRAIT_ASSET_URI}])).values());
      const nodes=[
        {id:'case-'+caseId,type:'case',label:center.rows[0].CASE_REF,detail:center.rows[0].PATTERN_LABEL},
        ...incidents.rows.map(i=>({id:'incident-'+i.INCIDENT_ID,type:'incident',label:i.INCIDENT_REF,INCIDENT_REF:i.INCIDENT_REF,detail:i.CATEGORY_NAME+' · '+i.SUBURB,address:i.ADDRESS_LINE_1+' · '+i.ADDRESS_POSTCODE})),
        ...personNodes,
        ...evidence.rows.map(e=>({id:'evidence-'+e.EVIDENCE_ID,type:'evidence',label:e.EVIDENCE_TYPE,EVIDENCE_REF:'E-'+e.EVIDENCE_ID,EVIDENCE_TYPE:e.EVIDENCE_TYPE,CREATED_AT:e.CREATED_AT,OBSERVED_DETAIL:e.OBSERVED_DETAIL,SHARED_MARKER:e.SHARED_MARKER,ASSET_URI:e.ASSET_URI,ASSET_CAPTION:e.ASSET_CAPTION,detail:e.OBSERVED_DETAIL||e.SHARED_MARKER||'Recorded evidence item'}))
      ];
      const edges=[
        ...incidents.rows.map(i=>({source:'case-'+caseId,target:'incident-'+i.INCIDENT_ID,type:'case involves'})),
        ...people.rows.map(p=>({source:'person-'+p.PERSON_ID,target:'incident-'+p.INCIDENT_ID,type:p.CONNECTION_TYPE.replaceAll('_',' ')})),
        ...evidence.rows.map(e=>({source:'incident-'+e.INCIDENT_ID,target:'evidence-'+e.EVIDENCE_ID,type:'has evidence'})),
        ...similarities.rows.map(s=>({source:'incident-'+s.SOURCE_INCIDENT_ID,target:'incident-'+s.MATCHED_INCIDENT_ID,type:'semantic similarity',score:Number(s.SIMILARITY_SCORE),reason:s.MATCH_REASON}))
      ];
      return {center:center.rows[0],nodes,edges};
    });
    if(!result)return res.status(404).json({error:'No authorised case relationship data found.'});
    res.json({...result,depth,technology:'Oracle Property Graph · SQL/PGQ model: crime_case_network',security:'Deep Data Security scoped incident joins'});
  } catch(e){console.error('Case graph error:',e);res.status(500).json({error:e.message});}
});
function incidentAskTopic(action, question) {
  const q=String(question||'').toLowerCase();
  const selected=['overview','local','similar','relationships'].includes(action) ? action : (q.includes('similar')||q.includes('pattern') ? 'similar' : q.includes('suburb')||q.includes('near')||q.includes('around') ? 'local' : q.includes('evidence')||q.includes('case')||q.includes('person')||q.includes('relationship') ? 'relationships' : 'overview');
  const topics={
    overview:{title:'Selected incident record',answer:'The selected incident record is shown with its authorised report, evidence, person-link, and case-link counts.',sql:`SELECT i.incident_ref,i.incident_status,i.occurred_at,i.suburb,i.location_type,i.modus_operandi,cat.category_name, p.area_name patrol_area,r.report_summary,(SELECT COUNT(*) FROM evidence_items e WHERE e.incident_id=i.incident_id) evidence_items,(SELECT COUNT(*) FROM person_incident_links l JOIN secure_persons_of_interest_v person ON person.person_id=l.person_id WHERE l.incident_id=i.incident_id) person_links,(SELECT COUNT(*) FROM case_incident_links cl WHERE cl.incident_id=i.incident_id) case_links FROM secure_crime_incidents_v i JOIN incident_categories cat ON cat.category_id=i.category_id JOIN patrol_areas p ON p.patrol_area_id=i.patrol_area_id JOIN secure_incident_reports_v r ON r.incident_id=i.incident_id WHERE i.incident_ref=:incidentRef`},
    local:{title:'Nearby incident context',answer:'These are authorised records from the same suburb, within 14 days either side of the selected incident. They are contextual records, not a finding of connection.',sql:`SELECT * FROM (SELECT related.incident_ref,related.occurred_at,related.incident_status,related.suburb,cat.category_name,related.modus_operandi,r.report_summary FROM secure_crime_incidents_v source JOIN secure_crime_incidents_v related ON related.suburb=source.suburb AND related.incident_id<>source.incident_id AND related.occurred_at BETWEEN source.occurred_at-INTERVAL '14' DAY AND source.occurred_at+INTERVAL '14' DAY JOIN incident_categories cat ON cat.category_id=related.category_id JOIN secure_incident_reports_v r ON r.incident_id=related.incident_id WHERE source.incident_ref=:incidentRef ORDER BY related.occurred_at DESC) WHERE ROWNUM<=20`},
    similar:{title:'Narrative-similar incident context',answer:'These are authorised records ranked by narrative-vector similarity to the selected incident. Similarity is contextual and is not evidence of a connection.',sql:`SELECT candidate.incident_ref,candidate.occurred_at,candidate.suburb,candidate.incident_status,cat.category_name,candidate.modus_operandi,r.report_summary,ROUND(1-VECTOR_DISTANCE(candidate_embedding.embedding,source_embedding.embedding,COSINE),4) similarity_score FROM secure_crime_incidents_v source JOIN incident_report_embeddings source_embedding ON source_embedding.incident_id=source.incident_id CROSS JOIN incident_report_embeddings candidate_embedding JOIN secure_crime_incidents_v candidate ON candidate.incident_id=candidate_embedding.incident_id JOIN secure_incident_reports_v r ON r.incident_id=candidate.incident_id JOIN incident_categories cat ON cat.category_id=candidate.category_id WHERE source.incident_ref=:incidentRef AND candidate.incident_id<>source.incident_id ORDER BY VECTOR_DISTANCE(candidate_embedding.embedding,source_embedding.embedding,COSINE) FETCH FIRST 12 ROWS ONLY`},
    relationships:{title:'Recorded relationship context',answer:'These are the authorised recorded case, evidence, and person-link details for the selected incident. They are record context only.',sql:`SELECT 'CASE' relationship_type,c.case_ref reference,c.case_status status,c.pattern_label detail FROM case_incident_links cl JOIN case_files c ON c.case_id=cl.case_id JOIN secure_crime_incidents_v i ON i.incident_id=cl.incident_id WHERE i.incident_ref=:incidentRef UNION ALL SELECT 'EVIDENCE',e.evidence_type,TO_CHAR(e.created_at,'YYYY-MM-DD HH24:MI:SS'),NULL FROM evidence_items e JOIN secure_crime_incidents_v i ON i.incident_id=e.incident_id WHERE i.incident_ref=:incidentRef UNION ALL SELECT 'PERSON LINK',person.person_ref,person.person_status,l.connection_type||': '||l.link_summary FROM person_incident_links l JOIN secure_persons_of_interest_v person ON person.person_id=l.person_id JOIN secure_crime_incidents_v i ON i.incident_id=l.incident_id WHERE i.incident_ref=:incidentRef`}
  };
  return {id:selected,...topics[selected]};
}
app.post('/api/incidents/ask', async (req,res) => { const incidentRef=String(req.body?.incidentRef||'').trim(),question=String(req.body?.question||'').trim(),action=String(req.body?.action||'').trim(); if(!incidentRef)return res.status(400).json({error:'Select an authorised incident before asking a question.'}); const topic=incidentAskTopic(action,question); try { const started=Date.now(),result=await db(req.demoUser,c=>c.execute(topic.sql,{incidentRef})); if(topic.id==='overview'&&!result.rows.length)return res.status(404).json({error:'No authorised incident record found.'}); res.json({incidentRef,question:question||topic.title,topic:topic.id,title:topic.title,answer:topic.answer,sql:topic.sql,columns:result.rows[0]?Object.keys(result.rows[0]):[],rows:result.rows,rowCount:result.rows.length,elapsed:Date.now()-started}); } catch(e) { console.error('Incident Ask Me error:',e);res.status(500).json({error:e.message});} });
const vectorIncidentAskTopic = incidentAskTopic;
incidentAskTopic = function(action, question) {
  const topic = vectorIncidentAskTopic(action, question);
  if (topic.id === 'similar') {
    topic.title = 'Similar incident context';
    topic.answer = 'These are authorised records sharing the selected incident’s detailed category or recorded modus operandi. They are contextual records, not evidence of a connection.';
    topic.sql = `SELECT * FROM (SELECT candidate.incident_ref,candidate.occurred_at,candidate.suburb,candidate.incident_status,cat.category_name,candidate.modus_operandi,r.report_summary,CASE WHEN candidate.modus_operandi=source.modus_operandi THEN 'same detailed category and modus operandi' ELSE 'same detailed category' END similarity_basis FROM secure_crime_incidents_v source JOIN secure_crime_incidents_v candidate ON candidate.incident_id<>source.incident_id AND (candidate.category_id=source.category_id OR (candidate.modus_operandi IS NOT NULL AND candidate.modus_operandi=source.modus_operandi)) JOIN incident_categories cat ON cat.category_id=candidate.category_id JOIN secure_incident_reports_v r ON r.incident_id=candidate.incident_id WHERE source.incident_ref=:incidentRef ORDER BY CASE WHEN candidate.modus_operandi=source.modus_operandi THEN 0 ELSE 1 END,candidate.occurred_at DESC) WHERE ROWNUM<=12`;
  }
  return topic;
};
