function validateLlmSql(value) { const sql=String(value||'').replace(/```sql|```/gi,'').trim().replace(/;\s*$/,''); const upper=sql.toUpperCase(); const allowed=new Set(['SECURE_CRIME_INCIDENTS_V','SECURE_INCIDENT_REPORTS_V','INCIDENT_CATEGORIES','PATROL_AREAS']); const objects=[...upper.matchAll(/\b(?:FROM|JOIN)\s+([A-Z_][A-Z0-9_$#]*)/g)].map(match=>match[1]); if(!/^SELECT\b/.test(upper)||upper.includes(';')||/\b(INSERT|UPDATE|DELETE|MERGE|ALTER|DROP|CREATE|GRANT|REVOKE|EXECUTE|BEGIN|DECLARE|DBMS_|UTL_|Z_BASE_)\b/.test(upper)||!objects.length||objects.some(object=>!allowed.has(object)))throw Error('The generated query was outside the approved read-only scoped views. Please rephrase the question.'); return sql; }
const SELECT_AI_V2_PROFILE = 'CRIMEDATA_SELECT_AI_V2';
const SELECT_AI_V2_MODEL = 'meta.llama-4-maverick-17b-128e-instruct-fp8';
function validateSelectAiV2Sql(value) { const raw=String(value||'').replace(/```(?:sql)?|```/gi,'').trim(); const selectAt=raw.search(/\bSELECT\b/i), sql=(selectAt>=0?raw.slice(selectAt):raw).replace(/\n\s*Exception encountered:[\s\S]*$/i,'').trim().replace(/;\s*$/,''); const upper=sql.toUpperCase(); const normalized=upper.replace(/"CRIME_DATA"\s*\.\s*/g,'').replace(/\bCRIME_DATA\s*\.\s*/g,'').replace(/"/g,''); const allowed=new Set(['SECURE_CRIME_INCIDENTS_V','SECURE_INCIDENT_REPORTS_V','SECURE_EVIDENCE_ITEMS_V','INCIDENT_CATEGORIES','PATROL_AREAS','SECURE_WATCHED_CRIME_PATTERNS_V','SECURE_WATCHED_PATTERN_INCIDENTS_V','SECURE_WATCHED_PATTERN_POSTS_V']); const objects=[...normalized.matchAll(/\b(?:FROM|JOIN)\s+([A-Z_][A-Z0-9_$#]*)/g)].map(match=>match[1]); if(!/^SELECT\b/.test(normalized)||upper.includes(';')||/\b(INSERT|UPDATE|DELETE|MERGE|ALTER|DROP|CREATE|GRANT|REVOKE|EXECUTE|BEGIN|DECLARE|DBMS_|UTL_|Z_BASE_|ALL_|USER_|DBA_)\b/.test(normalized)||!objects.length||objects.some(object=>!allowed.has(object)))throw Error('Select AI generated a query outside the approved read-only incident-data scope. Please rephrase the question.'); return sql; }
async function selectAiV2Generate(demoUser,prompt,attempt=1) { const generated=await db(demoUser,c=>ops.nativeExecute(c,{feature:'Ask IncidentData V2 SQL generation',profile:SELECT_AI_V2_PROFILE,stage:'sql',attempt,validate:r=>validateSelectAiV2Sql(r.rows?.[0]?.GENERATED_SQL)},`SELECT DBMS_CLOUD_AI.GENERATE(prompt=>:prompt,profile_name=>:profile_name,action=>'showsql') generated_sql FROM dual`,{prompt,profile_name:SELECT_AI_V2_PROFILE},{fetchInfo:{GENERATED_SQL:{type:oracledb.STRING}}})); return validateSelectAiV2Sql(generated.rows?.[0]?.GENERATED_SQL); }
