app.post('/api/incidents/ask-oci', async (req,res) => {
  const incidentRef=String(req.body?.incidentRef||'').trim(), question=String(req.body?.question||'').trim();
  if(!incidentRef||!question) return res.status(400).json({error:'Select an incident and enter a question.'});
  try {
    const started=Date.now();
    let generatedSql=validateLlmSql(await ociGenAiGenerate(`${OCI_SQL_SYSTEM}\n\nSelected incident: ${incidentRef}.\nQuestion: ${question}`, 900,{stage:'sql',validate:validateLlmSql}));
    let result;
    try { result=await db(req.demoUser,c=>c.execute(`SELECT * FROM (${generatedSql}) WHERE ROWNUM<=100`)); }
    catch(firstError) {
      generatedSql=validateLlmSql(await ociGenAiGenerate(`${OCI_SQL_SYSTEM}\n\nSelected incident: ${incidentRef}.\nQuestion: ${question}\nThe previous Oracle SQL failed with: ${firstError.message}\nGenerate a corrected query using the exact column names in the instructions.`, 900,{stage:'sql',attempt:2,validate:validateLlmSql}));
      result=await db(req.demoUser,c=>c.execute(`SELECT * FROM (${generatedSql}) WHERE ROWNUM<=100`));
    }
    const rows=result.rows||[];
    const answer=await ociGenAiGenerate(`You are a governed IncidentData assistant. Give a concise factual answer using only the supplied synthetic, scoped query results. State when no rows were returned. Do not make recommendations or infer responsibility.\n\nQuestion: ${question}\nReturned authorised rows: ${JSON.stringify(rows.slice(0,30))}`, 900,{stage:'answer'});
    const { model, region }=await ociGenAiConfig();
    await db(req.demoUser,async c=>{await c.execute(`INSERT INTO analyst_actions(user_name,action_type,payload) VALUES(:demoUser,:action,JSON(:payload))`,{demoUser:req.demoUser,action:'oci_genai_scoped_query',payload:JSON.stringify({incidentRef,question,generatedSql,rowCount:rows.length,model,region})});await c.commit();});
    res.json({incidentRef,question,title:'Ask Me (OCI GenAI)',answer,generatedSql,columns:rows[0]?Object.keys(rows[0]):[],rows,rowCount:rows.length,elapsed:Date.now()-started,model:`${model} · ${region}`});
  } catch(e) { console.error('OCI GenAI scoped query error:',e); res.status(400).json({error:e.message}); }
});
